{"version":3,"sources":["../scss/profile_remove_store.scss","../scss/_mixins.scss","../scss/_variables.scss","profile_remove_store.css"],"names":[],"mappings":"AAIE;EACE,iBAAA;ECJA,uCAAA;EACA,gBDIoC;ECHpC,kBAAA;EACA,YCHW;EDIX,eDC8B;EAC9B,kBAAA;EACA,mBAAA;AGCJ;;AHGA;EACE,aAAA;EACA,mBAAA;EACA,SAAA;EACA,uBAAA;AGAF;AHEE;EACE,gBAAA;EACA,kBAAA;AGAJ;AHGE;EACE,aAAA;ECvBA,uCAAA;EACA,gBDuBoC;ECtBpC,kBAAA;EACA,YCHW;EDIX,eDoB8B;EAC9B,kBAAA;EACA,yBAAA;EACA,kBAAA;EACA,WAAA;EACA,gBAAA;AGGJ","file":"profile_remove_store.css","sourcesContent":["@import \"./variables\";\n@import \"./mixins\";\n\n.main__info {\n  & h1 {\n    padding-top: 40px;\n    @include fonts($defaultColor, 24px, 600);\n    text-align: center;\n    margin-bottom: 20px;\n  }\n}\n\n.buttons_for_delete {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  justify-content: center;\n\n  & a {\n    max-width: 320px;\n    text-align: center;\n  }\n  \n  & button {\n    padding: 10px;\n    @include fonts($defaultColor, 14px, 400);\n    text-align: center;\n    border: 1px solid $gray;\n    border-radius: 8px;\n    width: 100%;\n    max-width: 320px;\n  }\n\n}\n","@mixin fonts($color,$size,$weight) {\n    font-family: 'Trebuchet MS', sans-serif;\n    font-weight: $weight;\n    font-style: normal;\n    color: $color;\n    font-size: $size;\n}","$mainColor: #3077a0;\n$defaultColor: black;\n$colorHover: red;\n$headerTopBorder: #bdd4e2;\n$buttonBg:linear-gradient(0deg, #4d95d6,#6e93dd,#c2d6f4);;\n$gray: #D4D4D4;\n$vipBg: #ff6163;\n$activeItem: #FFFFCA;\n$userSearchBg: #CFE6FE;\n$asideLinksColor: #307792;\n$asideExitColor: rgb(0, 128, 0);",".main__info h1 {\n  padding-top: 40px;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 600;\n  font-style: normal;\n  color: black;\n  font-size: 24px;\n  text-align: center;\n  margin-bottom: 20px;\n}\n\n.buttons_for_delete {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  justify-content: center;\n}\n.buttons_for_delete a {\n  max-width: 320px;\n  text-align: center;\n}\n.buttons_for_delete button {\n  padding: 10px;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n  text-align: center;\n  border: 1px solid #D4D4D4;\n  border-radius: 8px;\n  width: 100%;\n  max-width: 320px;\n}"]}width: 100%;\n  max-width: 320px;\n}"]}